SELECT s.SESSION_ID AS id_external FROM BRAZE_USER_EVENT_DEMO_DATASET.USERS_BEHAVIORS_APP_SESSIONSTART_VIEW s WHERE FROM_UNIXTIME(s.TIME) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(s.TIME) < '2026-01-31 23:59:59' ORDER BY s.TIME DESC LIMIT 10;
SELECT COUNT(*) AS event_cnt FROM BRAZE_USER_EVENT_DEMO_DATASET.USERS_BEHAVIORS_APP_SESSIONSTART_VIEW s WHERE FROM_UNIXTIME(s.TIME) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(s.TIME) < '2026-01-31 23:59:59';
SELECT COUNT(DISTINCT e.APP_ID) AS distinct_entity_cnt FROM BRAZE_USER_EVENT_DEMO_DATASET.USERS_BEHAVIORS_CUSTOMEVENT_VIEW e WHERE FROM_UNIXTIME(e.TIME) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(e.TIME) < '2026-01-31 23:59:59';
SELECT s.PLATFORM AS category_topic, COUNT(*) AS event_cnt FROM BRAZE_USER_EVENT_DEMO_DATASET.USERS_BEHAVIORS_APP_SESSIONSTART_VIEW s WHERE FROM_UNIXTIME(s.TIME) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(s.TIME) < '2026-01-31 23:59:59' GROUP BY s.PLATFORM ORDER BY event_cnt DESC LIMIT 10;
SELECT e.PLATFORM AS category_topic, COUNT(DISTINCT e.APP_ID) AS distinct_entity_cnt FROM BRAZE_USER_EVENT_DEMO_DATASET.USERS_BEHAVIORS_CUSTOMEVENT_VIEW e WHERE FROM_UNIXTIME(e.TIME) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(e.TIME) < '2026-01-31 23:59:59' GROUP BY e.PLATFORM ORDER BY distinct_entity_cnt DESC LIMIT 10;
SELECT s.DEVICE_MODEL AS name_entity, COUNT(*) AS event_cnt FROM BRAZE_USER_EVENT_DEMO_DATASET.USERS_BEHAVIORS_APP_SESSIONSTART_VIEW s WHERE FROM_UNIXTIME(s.TIME) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(s.TIME) < '2026-01-31 23:59:59' GROUP BY s.DEVICE_MODEL ORDER BY event_cnt DESC LIMIT 10;
SELECT m.USER_ID AS rel_person, COUNT(*) AS event_cnt FROM BRAZE_USER_EVENT_DEMO_DATASET.USERS_MESSAGES_EMAIL_OPEN_VIEW m WHERE FROM_UNIXTIME(m.TIME) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(m.TIME) < '2026-01-31 23:59:59' GROUP BY m.USER_ID ORDER BY event_cnt DESC LIMIT 10;
SELECT DATE(FROM_UNIXTIME(s.TIME)) AS day, COUNT(*) AS event_cnt FROM BRAZE_USER_EVENT_DEMO_DATASET.USERS_BEHAVIORS_APP_SESSIONSTART_VIEW s WHERE s.TIME >= UNIX_TIMESTAMP('2001-01-01 00:00:00') AND s.TIME < UNIX_TIMESTAMP('2026-01-31 23:59:59') GROUP BY day ORDER BY day;
SELECT DATE(FROM_UNIXTIME(s.TIME)) AS day, s.PLATFORM AS category_topic, COUNT(*) AS event_cnt FROM BRAZE_USER_EVENT_DEMO_DATASET.USERS_BEHAVIORS_APP_SESSIONSTART_VIEW s WHERE FROM_UNIXTIME(s.TIME) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(s.TIME) < '2026-01-31 23:59:59' GROUP BY day, s.PLATFORM ORDER BY day, event_cnt DESC;
SELECT s.DEVICE_MODEL AS name_entity, COUNT(*) AS event_cnt FROM BRAZE_USER_EVENT_DEMO_DATASET.USERS_BEHAVIORS_APP_SESSIONSTART_VIEW s WHERE FROM_UNIXTIME(s.TIME) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(s.TIME) < '2026-01-31 23:59:59' GROUP BY s.DEVICE_MODEL HAVING COUNT(*) >= 10 ORDER BY event_cnt DESC;
WITH topic_cnt AS ( SELECT s.PLATFORM AS topic, COUNT(*) AS cnt FROM BRAZE_USER_EVENT_DEMO_DATASET.USERS_BEHAVIORS_APP_SESSIONSTART_VIEW s WHERE FROM_UNIXTIME(s.TIME) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(s.TIME) < '2026-01-31 23:59:59' GROUP BY s.PLATFORM ), avg_cnt AS ( SELECT AVG(cnt) AS avg_cnt FROM topic_cnt ) SELECT topic, cnt FROM topic_cnt WHERE cnt > (SELECT avg_cnt FROM avg_cnt) ORDER BY cnt DESC LIMIT 10;
SELECT m.USER_ID AS rel_person, m.IP_POOL AS category_topic, COUNT(*) AS event_cnt FROM BRAZE_USER_EVENT_DEMO_DATASET.USERS_MESSAGES_EMAIL_SEND_VIEW m WHERE FROM_UNIXTIME(m.TIME) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(m.TIME) < '2026-01-31 23:59:59' GROUP BY m.USER_ID, m.IP_POOL ORDER BY event_cnt DESC LIMIT 10;
SELECT COUNT(*) AS row_cnt FROM CENSUS_GALAXY__AIML_MODEL_DATA_ENRICHMENT_SAMPLE.FACT_CENSUSVALUES_ACS2021 f;
SELECT COUNT(DISTINCT f.BlockGroupID) AS distinct_external_cnt FROM CENSUS_GALAXY__AIML_MODEL_DATA_ENRICHMENT_SAMPLE.FACT_CENSUSVALUES_ACS2021 f;
SELECT COUNT(DISTINCT x.ToZipCode) AS distinct_entity_cnt FROM CENSUS_GALAXY__AIML_MODEL_DATA_ENRICHMENT_SAMPLE.XREF_TRACTTOZIP_RESIDENTIAL x;
SELECT g.StateName AS name_entity, COUNT(*) AS event_cnt FROM CENSUS_GALAXY__AIML_MODEL_DATA_ENRICHMENT_SAMPLE.DIM_CENSUSGEOGRAPHY g GROUP BY g.StateName ORDER BY event_cnt DESC LIMIT 10;
SELECT distinct g.CountyFIPS AS id_external FROM CENSUS_GALAXY__AIML_MODEL_DATA_ENRICHMENT_SAMPLE.DIM_CENSUSGEOGRAPHY g WHERE g.CountyName LIKE '%Kings%' ORDER BY g.CountyFIPS LIMIT 10;
SELECT lu.PreferredCityStateAbbrev AS location, COUNT(DISTINCT lu.ZipCode) AS distinct_external_cnt FROM CENSUS_GALAXY__AIML_MODEL_DATA_ENRICHMENT_SAMPLE.LU_GEOGRAPHYEXPANDED lu GROUP BY lu.PreferredCityStateAbbrev ORDER BY distinct_external_cnt DESC LIMIT 10;
SELECT t.id AS id_external FROM CRYPTO.CRYPTO_ZILLIQA_TRANSACTIONS t WHERE t.data LIKE '%Mint%' ORDER BY t.block_timestamp DESC LIMIT 10;
SELECT t.id AS id_external FROM CRYPTO.CRYPTO_ZILLIQA_TRANSACTIONS t WHERE FROM_UNIXTIME(t.block_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(t.block_timestamp / 1000000) < '2026-01-31 23:59:59' ORDER BY t.block_timestamp DESC LIMIT 10;
SELECT t.id AS id_external FROM CRYPTO.CRYPTO_ZILLIQA_TRANSACTIONS t WHERE t.success = 'Business' ORDER BY t.block_timestamp DESC LIMIT 10;
SELECT t.id AS id_external FROM CRYPTO.CRYPTO_ZILLIQA_TRANSACTIONS t WHERE FROM_UNIXTIME(t.block_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(t.block_timestamp / 1000000) < '2026-01-31 23:59:59' AND t.success = True AND t.data LIKE CONCAT('%', '%Mint%', '%') ORDER BY t.block_timestamp DESC LIMIT 10;
SELECT COUNT(*) AS event_cnt FROM CRYPTO.CRYPTO_ZILLIQA_TRANSACTIONS t WHERE FROM_UNIXTIME(t.block_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(t.block_timestamp / 1000000) < '2026-01-31 23:59:59';
SELECT COUNT(DISTINCT t.sender) AS distinct_entity_cnt FROM CRYPTO.CRYPTO_ZILLIQA_TRANSACTIONS t WHERE FROM_UNIXTIME(t.block_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(t.block_timestamp / 1000000) < '2026-01-31 23:59:59';
SELECT SUM(x.amount) AS total_amount FROM CRYPTO.CRYPTO_ZILLIQA_TRANSITIONS x WHERE FROM_UNIXTIME(x.block_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(x.block_timestamp / 1000000) < '2026-01-31 23:59:59';
SELECT AVG(t.gas_price) AS avg_amount, AVG(t.gas_limit) AS avg_quantity FROM CRYPTO.CRYPTO_ZILLIQA_TRANSACTIONS t WHERE FROM_UNIXTIME(t.block_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(t.block_timestamp / 1000000) < '2026-01-31 23:59:59';
SELECT x.tag AS category_topic, COUNT(*) AS event_cnt FROM CRYPTO.CRYPTO_ZILLIQA_TRANSITIONS x WHERE FROM_UNIXTIME(x.block_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(x.block_timestamp / 1000000) < '2026-01-31 23:59:59' GROUP BY x.tag ORDER BY event_cnt DESC LIMIT 10;
SELECT x.tag AS category_topic, COUNT(DISTINCT x.addr) AS distinct_entity_cnt FROM CRYPTO.CRYPTO_ZILLIQA_TRANSITIONS x WHERE FROM_UNIXTIME(x.block_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(x.block_timestamp / 1000000) < '2026-01-31 23:59:59' GROUP BY x.tag ORDER BY distinct_entity_cnt DESC LIMIT 10;
SELECT tk.name AS name_entity, SUM(tt.value) AS total_amount FROM CRYPTO.CRYPTO_ETHEREUM_CLASSIC_TOKEN_TRANSFERS tt JOIN CRYPTO.CRYPTO_ETHEREUM_CLASSIC_TOKENS tk ON tk.address = tt.token_address WHERE FROM_UNIXTIME(tt.block_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(tt.block_timestamp / 1000000) < '2026-01-31 23:59:59' GROUP BY tk.name ORDER BY total_amount DESC LIMIT 10;
SELECT DATE(FROM_UNIXTIME(t.block_timestamp / 1000000.0)) AS day, COUNT(*) AS event_cnt FROM CRYPTO.CRYPTO_ZILLIQA_TRANSACTIONS t WHERE t.block_timestamp >= UNIX_TIMESTAMP('2001-01-01 00:00:00') * 1000000.0 AND t.block_timestamp < UNIX_TIMESTAMP('2026-01-31 23:59:59') * 1000000.0 GROUP BY day ORDER BY day;
SELECT DATE_FORMAT(FROM_UNIXTIME(x.block_timestamp / 1000000.0), '%Y-%m-01') AS month, SUM(x.amount) AS total_amount FROM CRYPTO.CRYPTO_ZILLIQA_TRANSITIONS x WHERE x.block_timestamp >= UNIX_TIMESTAMP('2001-01-01 00:00:00') * 1000000.0 AND x.block_timestamp < UNIX_TIMESTAMP('2026-01-31 23:59:59') * 1000000.0 GROUP BY month ORDER BY month;
SELECT DATE(FROM_UNIXTIME(x.block_timestamp / 1000000.0)) AS day, x.tag AS category_topic, COUNT(*) AS event_cnt FROM CRYPTO.CRYPTO_ZILLIQA_TRANSITIONS x WHERE FROM_UNIXTIME(x.block_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(x.block_timestamp / 1000000) < '2026-01-31 23:59:59' GROUP BY day, x.tag ORDER BY day, event_cnt DESC;
SELECT tk.name AS name_entity, AVG(tt.value) AS avg_amount FROM CRYPTO.CRYPTO_ETHEREUM_CLASSIC_TOKEN_TRANSFERS tt JOIN CRYPTO.CRYPTO_ETHEREUM_CLASSIC_TOKENS tk ON tk.address = tt.token_address WHERE FROM_UNIXTIME(tt.block_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(tt.block_timestamp / 1000000) < '2026-01-31 23:59:59' AND tt.value IS NOT NULL GROUP BY tk.name ORDER BY avg_amount DESC LIMIT 10;
WITH topic_cnt AS ( SELECT x.tag AS topic, COUNT(*) AS cnt FROM CRYPTO.CRYPTO_ZILLIQA_TRANSITIONS x WHERE FROM_UNIXTIME(x.block_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(x.block_timestamp / 1000000) < '2026-01-31 23:59:59' GROUP BY x.tag ), avg_cnt AS ( SELECT AVG(cnt) AS avg_cnt FROM topic_cnt ) SELECT topic, cnt FROM topic_cnt WHERE cnt > (SELECT avg_cnt FROM avg_cnt) ORDER BY cnt DESC LIMIT 10;
SELECT x.tag AS category_topic, SUM(x.amount) AS total_amount FROM CRYPTO.CRYPTO_ZILLIQA_TRANSITIONS x WHERE FROM_UNIXTIME(x.block_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(x.block_timestamp / 1000000) < '2026-01-31 23:59:59' GROUP BY x.tag ORDER BY total_amount DESC LIMIT 10;
SELECT x.tag AS category_topic, SUM(x.amount) AS total_amount FROM CRYPTO.CRYPTO_ZILLIQA_TRANSITIONS x WHERE FROM_UNIXTIME(x.block_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(x.block_timestamp / 1000000) < '2026-01-31 23:59:59' GROUP BY x.tag HAVING SUM(x.amount) >= 1000 ORDER BY total_amount DESC;
SELECT x.tag AS category_topic, CAST(SUM(CASE WHEN x.accepted = False THEN 1 ELSE 0 END) AS DOUBLE) / COUNT(*) AS ratio_in_status FROM CRYPTO.CRYPTO_ZILLIQA_TRANSITIONS x WHERE x.block_timestamp >= UNIX_TIMESTAMP('2001-01-01 00:00:00') * 1000000.0 AND x.block_timestamp < UNIX_TIMESTAMP('2026-01-31 23:59:59') * 1000000.0 GROUP BY x.tag ORDER BY ratio_in_status DESC LIMIT 10;
SELECT SUM(t.gas_limit) AS total_quantity FROM CRYPTO.CRYPTO_ZILLIQA_TRANSACTIONS t WHERE FROM_UNIXTIME(t.block_timestamp / 1000000) >= '2001-01-01 00:00:00' AND FROM_UNIXTIME(t.block_timestamp / 1000000) < '2026-01-31 23:59:59';
SELECT uo.OfferNo AS id_external FROM EDUCATION_BUSINESS.UNIVERSITY_OFFERING uo WHERE uo.OffYear >= '2009' AND uo.OffYear <= '2010' ORDER BY uo.OffYear DESC LIMIT 10;
SELECT COUNT(*) AS event_cnt FROM EDUCATION_BUSINESS.UNIVERSITY_OFFERING uo WHERE uo.OffYear >= '2009' AND uo.OffYear <= '2010';
