SELECT AVG(wo.total_amt_usd) AS avg_amount, AVG(wo.total) AS avg_quantity FROM EDUCATION_BUSINESS.WEB_ORDERS wo WHERE CAST(wo.occurred_at AS DATETIME) >= '2001-01-01 00:00:00' AND CAST(wo.occurred_at AS DATETIME) < '2026-01-31 23:59:59';
