SELECT uc.CrsDesc AS name_entity, COUNT(*) AS event_cnt FROM EDUCATION_BUSINESS.UNIVERSITY_OFFERING uo JOIN EDUCATION_BUSINESS.UNIVERSITY_COURSE uc ON uo.CourseNo = uc.CourseNo WHERE uo.OffYear >= '2009' AND uo.OffYear <= '2010' GROUP BY uc.CrsDesc ORDER BY event_cnt DESC LIMIT 10;
SELECT wa.name AS name_entity, SUM(wo.total_amt_usd) AS total_amount FROM EDUCATION_BUSINESS.WEB_ORDERS wo JOIN EDUCATION_BUSINESS.WEB_ACCOUNTS wa ON wo.account_id = wa.id WHERE wo.occurred_at >= '2001-01-01 00:00:00' AND wo.occurred_at < '2026-01-31 23:59:59' GROUP BY wa.name ORDER BY total_amount DESC LIMIT 10;
SELECT uo.FacNo AS rel_person, COUNT(*) AS event_cnt FROM EDUCATION_BUSINESS.UNIVERSITY_OFFERING uo WHERE uo.OffYear >= '2009' AND uo.OffYear <= '2010' GROUP BY uo.FacNo ORDER BY event_cnt DESC LIMIT 10;
SELECT DATE_FORMAT(CAST(wo.occurred_at AS DATETIME), '%Y-%m-01') AS month, SUM(wo.total_amt_usd) AS total_amount FROM EDUCATION_BUSINESS.WEB_ORDERS wo WHERE CAST(wo.occurred_at AS DATETIME) >= '2001-01-01 00:00:00' AND CAST(wo.occurred_at AS DATETIME) < '2026-01-31 23:59:59' GROUP BY month ORDER BY month;
SELECT uc.CrsDesc AS name_entity, COUNT(*) AS event_cnt FROM EDUCATION_BUSINESS.UNIVERSITY_OFFERING uo JOIN EDUCATION_BUSINESS.UNIVERSITY_COURSE uc ON uo.CourseNo = uc.CourseNo WHERE uo.OffYear >= '2009' AND uo.OffYear <= '2010' GROUP BY uc.CrsDesc HAVING COUNT(*) >= 5 ORDER BY event_cnt DESC;
SELECT wa.name AS name_entity, AVG(wo.total_amt_usd) AS avg_amount FROM EDUCATION_BUSINESS.WEB_ORDERS wo JOIN EDUCATION_BUSINESS.WEB_ACCOUNTS wa ON wo.account_id = wa.id WHERE CAST(wo.occurred_at AS DATETIME) >= '2001-01-01 00:00:00' AND CAST(wo.occurred_at AS DATETIME) < '2026-01-31 23:59:59' AND wo.total_amt_usd IS NOT NULL GROUP BY wa.name ORDER BY avg_amount DESC LIMIT 10;
WITH topic_cnt AS ( SELECT uo.OffTerm AS topic, COUNT(*) AS cnt FROM EDUCATION_BUSINESS.UNIVERSITY_OFFERING uo WHERE uo.OffYear >= '2009' AND uo.OffYear <= '2010' GROUP BY uo.OffTerm ), avg_cnt AS ( SELECT AVG(cnt) AS avg_cnt FROM topic_cnt ) SELECT topic, cnt FROM topic_cnt WHERE cnt > (SELECT avg_cnt FROM avg_cnt) ORDER BY cnt DESC LIMIT 10;
SELECT uo.FacNo AS rel_person, uo.OffTerm AS category_topic, COUNT(*) AS event_cnt FROM EDUCATION_BUSINESS.UNIVERSITY_OFFERING uo WHERE uo.OffYear >= '2009' AND uo.OffYear <= '2010' GROUP BY uo.FacNo, uo.OffTerm ORDER BY event_cnt DESC LIMIT 10;
SELECT SUM(wo.total) AS total_quantity FROM EDUCATION_BUSINESS.WEB_ORDERS wo WHERE CAST(wo.occurred_at AS DATETIME) >= '2001-01-01 00:00:00' AND CAST(wo.occurred_at AS DATETIME) < '2026-01-31 23:59:59';
