SELECT AVG(e.EVENT_VALUE_IN_USD) AS avg_amount FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE_EVENTS_20210131 e WHERE FROM_UNIXTIME(e.EVENT_TIMESTAMP / 1000000) >= '2021-01-31 09:00:00' AND FROM_UNIXTIME(e.EVENT_TIMESTAMP / 1000000) < '2021-01-31 17:00:00';
SELECT e.PLATFORM AS category_topic, COUNT(*) AS event_cnt FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE_EVENTS_20210131 e WHERE FROM_UNIXTIME(e.EVENT_TIMESTAMP / 1000000) >= '2021-01-31 09:00:00' AND FROM_UNIXTIME(e.EVENT_TIMESTAMP / 1000000) < '2021-01-31 17:00:00' GROUP BY e.PLATFORM ORDER BY event_cnt DESC LIMIT 10;
SELECT e.PLATFORM AS category_topic, COUNT(DISTINCT e.STREAM_ID) AS distinct_entity_cnt FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE_EVENTS_20210131 e WHERE FROM_UNIXTIME(e.EVENT_TIMESTAMP / 1000000) >= '2021-01-31 09:00:00' AND FROM_UNIXTIME(e.EVENT_TIMESTAMP / 1000000) < '2021-01-31 17:00:00' GROUP BY e.PLATFORM ORDER BY distinct_entity_cnt DESC LIMIT 10;
