SELECT CAST(e.TRAFFIC_SOURCE AS CHAR) AS name_entity, SUM(e.EVENT_VALUE_IN_USD) AS total_amount FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE_EVENTS_20210131 e WHERE FROM_UNIXTIME(e.EVENT_TIMESTAMP / 1000000) >= '2021-01-31 09:00:00' AND FROM_UNIXTIME(e.EVENT_TIMESTAMP / 1000000) < '2021-01-31 17:00:00' GROUP BY CAST(e.TRAFFIC_SOURCE AS CHAR) ORDER BY total_amount DESC LIMIT 10;
