SELECT DATE_FORMAT(FROM_UNIXTIME(e.EVENT_TIMESTAMP / 1000000.0), '%Y-%m-%d %H:00:00') AS hour, SUM(e.EVENT_VALUE_IN_USD) AS total_amount FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE_EVENTS_20210131 e WHERE e.EVENT_TIMESTAMP >= UNIX_TIMESTAMP('2021-01-31 09:00:00') * 1000000.0 AND e.EVENT_TIMESTAMP < UNIX_TIMESTAMP('2021-01-31 17:00:00') * 1000000.0 GROUP BY hour ORDER BY hour;
SELECT DATE_FORMAT(FROM_UNIXTIME(e.EVENT_TIMESTAMP / 1000000.0), '%Y-%m-%d %H:00:00') AS hour, e.PLATFORM AS category_topic, COUNT(*) AS event_cnt FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE_EVENTS_20210131 e WHERE FROM_UNIXTIME(e.EVENT_TIMESTAMP / 1000000) >= '2021-01-31 09:00:00' AND FROM_UNIXTIME(e.EVENT_TIMESTAMP / 1000000) < '2021-01-31 17:00:00' GROUP BY hour, e.PLATFORM ORDER BY hour, event_cnt DESC;
