SELECT DISTINCT CAST(e.DEVICE AS CHAR) AS name_entity FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE_EVENTS_20210131 e WHERE FROM_UNIXTIME(e.EVENT_TIMESTAMP / 1000000) >= '2021-01-31 09:00:00' AND FROM_UNIXTIME(e.EVENT_TIMESTAMP / 1000000) < '2021-01-31 17:00:00' AND CAST(e.EVENT_PARAMS AS CHAR) LIKE '%item%' ORDER BY name_entity LIMIT 10;
SELECT DISTINCT CAST(e.DEVICE AS CHAR) AS name_entity FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE_EVENTS_20210131 e WHERE FROM_UNIXTIME(e.EVENT_TIMESTAMP / 1000000) >= '2021-01-31 09:00:00' AND FROM_UNIXTIME(e.EVENT_TIMESTAMP / 1000000) < '2021-01-31 17:00:00' AND CAST(e.EVENT_PARAMS AS CHAR) LIKE '%item%' ORDER BY name_entity LIMIT 10;
WITH topic_cnt AS ( SELECT e.PLATFORM AS topic, COUNT(*) AS cnt FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE_EVENTS_20210131 e WHERE FROM_UNIXTIME(e.EVENT_TIMESTAMP / 1000000) >= '2021-01-31 09:00:00' AND FROM_UNIXTIME(e.EVENT_TIMESTAMP / 1000000) < '2021-01-31 17:00:00' GROUP BY e.PLATFORM ), avg_cnt AS ( SELECT AVG(cnt) AS avg_cnt FROM topic_cnt ) SELECT topic, cnt FROM topic_cnt WHERE cnt >= (SELECT avg_cnt FROM avg_cnt) ORDER BY cnt DESC LIMIT 10;
SELECT e.PLATFORM AS category_topic, SUM(e.EVENT_VALUE_IN_USD) AS total_amount FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE_EVENTS_20210131 e WHERE FROM_UNIXTIME(e.EVENT_TIMESTAMP / 1000000) >= '2021-01-31 09:00:00' AND FROM_UNIXTIME(e.EVENT_TIMESTAMP / 1000000) < '2021-01-31 17:00:00' GROUP BY e.PLATFORM ORDER BY total_amount DESC LIMIT 10;
SELECT e.PLATFORM AS category_topic, SUM(e.EVENT_VALUE_IN_USD) AS total_amount FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE_EVENTS_20210131 e WHERE FROM_UNIXTIME(e.EVENT_TIMESTAMP / 1000000) >= '2021-01-31 09:00:00' AND FROM_UNIXTIME(e.EVENT_TIMESTAMP / 1000000) < '2021-01-31 17:00:00' GROUP BY e.PLATFORM HAVING SUM(e.EVENT_VALUE_IN_USD) >= 1000 ORDER BY total_amount DESC;
WITH agg AS ( SELECT e.PLATFORM AS topic, CAST(e.TRAFFIC_SOURCE AS CHAR) AS entity, SUM(e.EVENT_VALUE_IN_USD) AS total_amount FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE_EVENTS_20210131 e WHERE FROM_UNIXTIME(e.EVENT_TIMESTAMP / 1000000) >= '2021-01-31 09:00:00' AND FROM_UNIXTIME(e.EVENT_TIMESTAMP / 1000000) < '2021-01-31 17:00:00' GROUP BY e.PLATFORM, CAST(e.TRAFFIC_SOURCE AS CHAR) ), ranked AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY topic ORDER BY total_amount DESC) AS rn FROM agg ) SELECT topic, entity, total_amount FROM ranked WHERE rn = 1 ORDER BY total_amount DESC LIMIT 10;
SELECT ei.uuid AS id_external FROM ods_szkjglxm.co_exchange_info ei WHERE ei.content LIKE '%nbsp%' ORDER BY ei.date DESC LIMIT 10;
SELECT ei.uuid AS id_external FROM ods_szkjglxm.co_exchange_info ei WHERE ei.date >= '2001-01-01 00:00:00' AND ei.date < '2026-01-31 23:59:59' ORDER BY ei.date DESC LIMIT 10;
SELECT ei.uuid AS id_external FROM ods_szkjglxm.co_exchange_info ei WHERE ei.status = 1 ORDER BY ei.date DESC LIMIT 10;
SELECT ei.uuid AS id_external FROM ods_szkjglxm.co_exchange_info ei WHERE ei.date >= '2001-01-01 00:00:00' AND ei.date < '2026-01-31 23:59:59' AND ei.status = 1 AND ei.content LIKE CONCAT('%', 'Native Tech', '%') ORDER BY ei.date DESC LIMIT 10;
SELECT COUNT(*) AS event_cnt FROM ods_szkjglxm.co_exchange_info ei WHERE ei.date >= '2001-01-01 00:00:00' AND ei.date < '2026-01-31 23:59:59';
SELECT COUNT(DISTINCT ei.partner_uuid) AS distinct_entity_cnt FROM ods_szkjglxm.co_exchange_info ei WHERE ei.date >= '2001-01-01 00:00:00' AND ei.date < '2026-01-31 23:59:59';
SELECT AVG(p.paper_scale) AS avg_quantity FROM ods_szkjglxm.intellectual_property_paper p WHERE p.submit_time >= '2001-01-01 00:00:00' AND p.submit_time < '2026-01-31 23:59:59';
SELECT p.delivery_type AS category_topic, COUNT(*) AS event_cnt FROM ods_szkjglxm.intellectual_property_paper p WHERE p.submit_time >= '2001-01-01 00:00:00' AND p.submit_time < '2026-01-31 23:59:59' GROUP BY p.delivery_type ORDER BY event_cnt DESC LIMIT 10;
SELECT p.delivery_type AS category_topic, COUNT(DISTINCT p.project_info_uuid) AS distinct_entity_cnt FROM ods_szkjglxm.intellectual_property_paper p WHERE p.submit_time >= '2001-01-01 00:00:00' AND p.submit_time < '2026-01-31 23:59:59' GROUP BY p.delivery_type ORDER BY distinct_entity_cnt DESC LIMIT 10;
SELECT p.paper_name AS name_entity, COUNT(*) AS event_cnt FROM ods_szkjglxm.intellectual_property_paper p WHERE p.submit_time >= '2001-01-01 00:00:00' AND p.submit_time < '2026-01-31 23:59:59' GROUP BY p.paper_name ORDER BY event_cnt DESC LIMIT 10;
SELECT ei.contact_id AS rel_person, COUNT(*) AS event_cnt FROM ods_szkjglxm.co_exchange_info ei WHERE ei.date >= '2001-01-01 00:00:00' AND ei.date < '2026-01-31 23:59:59' GROUP BY ei.contact_id ORDER BY event_cnt DESC LIMIT 10;
SELECT DATE( ei.date) AS day, COUNT(*) AS event_cnt FROM ods_szkjglxm.co_exchange_info ei WHERE ei.date >= '2001-01-01 00:00:00' AND ei.date < '2026-01-31 23:59:59' GROUP BY day ORDER BY day;
SELECT DATE( p.submit_time) AS day, p.delivery_type AS category_topic, COUNT(*) AS event_cnt FROM ods_szkjglxm.intellectual_property_paper p WHERE p.submit_time >= '2001-01-01 00:00:00' AND p.submit_time < '2026-01-31 23:59:59' GROUP BY day, p.delivery_type ORDER BY day, event_cnt DESC;
SELECT ei.partner_name AS name_entity, COUNT(*) AS event_cnt FROM ods_szkjglxm.co_exchange_info ei WHERE ei.date >= '2001-01-01 00:00:00' AND ei.date < '2026-01-31 23:59:59' GROUP BY ei.partner_name HAVING COUNT(*) >= 10 ORDER BY event_cnt DESC;
SELECT DISTINCT p.paper_name AS name_entity FROM ods_szkjglxm.intellectual_property_paper p WHERE p.submit_time >= '2001-01-01 00:00:00' AND p.submit_time < '2026-01-31 23:59:59' AND p.paper_abstract LIKE '%good%' ORDER BY p.paper_name LIMIT 10;
WITH topic_cnt AS ( SELECT p.delivery_type AS topic, COUNT(*) AS cnt FROM ods_szkjglxm.intellectual_property_paper p WHERE p.submit_time >= '2001-01-01 00:00:00' AND p.submit_time < '2026-01-31 23:59:59' GROUP BY p.delivery_type ), avg_cnt AS ( SELECT AVG(cnt) AS avg_cnt FROM topic_cnt ) SELECT topic, cnt FROM topic_cnt WHERE cnt > (SELECT avg_cnt FROM avg_cnt) ORDER BY cnt DESC LIMIT 10;
SELECT p.paper_writer AS rel_person, p.delivery_type AS category_topic, COUNT(*) AS event_cnt FROM ods_szkjglxm.intellectual_property_paper p WHERE p.submit_time >= '2001-01-01 00:00:00' AND p.submit_time < '2026-01-31 23:59:59' GROUP BY p.paper_writer, p.delivery_type ORDER BY event_cnt DESC LIMIT 10;
SELECT ei.tech_uuid AS category_topic, CAST(SUM(CASE WHEN ei.status = 0 THEN 1 ELSE 0 END) AS DOUBLE) / COUNT(*) AS ratio_in_status FROM ods_szkjglxm.co_exchange_info ei WHERE ei.date >= '2001-01-01 00:00:00' AND ei.date < '2026-01-31 23:59:59' GROUP BY ei.tech_uuid ORDER BY ratio_in_status DESC LIMIT 10;
SELECT SUM(p.paper_scale) AS total_quantity FROM ods_szkjglxm.intellectual_property_paper p WHERE p.submit_time >= '2001-01-01 00:00:00' AND p.submit_time < '2026-01-31 23:59:59';
SELECT p.delivery_type AS category_topic, SUM(p.paper_scale) AS total_quantity FROM ods_szkjglxm.intellectual_property_paper p WHERE p.submit_time >= '2001-01-01 00:00:00' AND p.submit_time < '2026-01-31 23:59:59' GROUP BY p.delivery_type ORDER BY total_quantity DESC LIMIT 10;
